CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('admin','coach','parent');
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),full_name VARCHAR(140) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role user_role NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,phone VARCHAR(30),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE coaches(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE REFERENCES users(id) ON DELETE SET NULL,full_name VARCHAR(140) NOT NULL,phone VARCHAR(30),specialty VARCHAR(120),status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE players(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),parent_user_id UUID REFERENCES users(id) ON DELETE SET NULL,full_name VARCHAR(140) NOT NULL,birth_date DATE,age_group VARCHAR(10) NOT NULL CHECK(age_group IN ('U-8','U-10','U-12','U-14','U-16','U-18')),parent_name VARCHAR(140),parent_phone VARCHAR(30),status VARCHAR(20) NOT NULL DEFAULT 'active',notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE training_schedules(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),title VARCHAR(180) NOT NULL,age_group VARCHAR(10) NOT NULL,starts_at TIMESTAMPTZ NOT NULL,location VARCHAR(180) NOT NULL,coach_id UUID REFERENCES coaches(id) ON DELETE SET NULL,notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE attendance(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),player_id UUID NOT NULL REFERENCES players(id) ON DELETE CASCADE,schedule_id UUID REFERENCES training_schedules(id) ON DELETE SET NULL,attendance_date DATE NOT NULL,status VARCHAR(15) NOT NULL CHECK(status IN ('present','permission','sick','absent')),notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(player_id,schedule_id,attendance_date));
CREATE TABLE fees(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),player_id UUID NOT NULL REFERENCES players(id) ON DELETE CASCADE,period VARCHAR(30) NOT NULL,amount BIGINT NOT NULL CHECK(amount>=0),due_date DATE,status VARCHAR(20) NOT NULL DEFAULT 'unpaid' CHECK(status IN ('unpaid','pending','paid')),paid_at TIMESTAMPTZ,receipt_reference TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(player_id,period));
CREATE TABLE registrations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),full_name VARCHAR(140) NOT NULL,birth_date DATE NOT NULL,age_group VARCHAR(10) NOT NULL,parent_name VARCHAR(140) NOT NULL,parent_phone VARCHAR(30) NOT NULL,notes TEXT,status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE matches(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),title VARCHAR(180) NOT NULL,kind VARCHAR(20) NOT NULL CHECK(kind IN ('friendly','tournament')),starts_at TIMESTAMPTZ NOT NULL,location VARCHAR(180) NOT NULL,age_group VARCHAR(10) NOT NULL,opponent VARCHAR(140),result VARCHAR(30),notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE player_evaluations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),player_id UUID NOT NULL REFERENCES players(id) ON DELETE CASCADE,coach_id UUID REFERENCES coaches(id) ON DELETE SET NULL,evaluated_on DATE NOT NULL,technique SMALLINT NOT NULL CHECK(technique BETWEEN 1 AND 10),physical SMALLINT NOT NULL CHECK(physical BETWEEN 1 AND 10),discipline SMALLINT NOT NULL CHECK(discipline BETWEEN 1 AND 10),mental SMALLINT NOT NULL CHECK(mental BETWEEN 1 AND 10),notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),title VARCHAR(180) NOT NULL,message TEXT NOT NULL,category VARCHAR(20) NOT NULL DEFAULT 'info',channel VARCHAR(20) NOT NULL DEFAULT 'in_app',scheduled_at TIMESTAMPTZ,status VARCHAR(20) NOT NULL DEFAULT 'draft',provider_reference TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_players_group ON players(age_group);CREATE INDEX idx_schedule_starts ON training_schedules(starts_at);CREATE INDEX idx_attendance_date ON attendance(attendance_date);CREATE INDEX idx_fees_status ON fees(status);
